import 'package:super_annotations/super_annotations.dart';

@CodeGen()
library main;

class MyAnnotation extends ClassAnnotation {
  const MyAnnotation();

  @override
  void apply(Class target, LibraryBuilder output) {
    output.body.add(Code('// Generated for ${target.name}'));
  }
}

@MyAnnotation()
class MyClass {
  final String data;
  MyClass(this.data);
}
